#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Projectiles;
using MVZ2Logic.Artifacts;
using MVZ2Logic.Definitions;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Auras;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Entities;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.GameContent.Artifacts
{
    [AutoArtifactDefinition(VanillaArtifactNames.krakensTentacle)]
    public class KrakensTentacle : ArtifactDefinition
    {
        public KrakensTentacle(string nsp, string name) : base(nsp, name)
        {
            AddAura(new Aura());
            AddTrigger(VanillaLevelCallbacks.PRE_PROJECTILE_SHOT, PreProjectileShotCallback);
        }
        public override void PostUpdate(Artifact artifact)
        {
            base.PostUpdate(artifact);
            artifact.SetGlowing(true);
        }
        private void PreProjectileShotCallback(VanillaLevelCallbacks.PreProjectileShotParams args, CallbackResult result)
        {
            var source = args.source;
            var level = source.Level;
            var shootParams = args.projectileArgs;
            if (source.Type != EntityTypes.PLANT || !source.IsFriendlyEntity())
                return;
            var artifact = level.GetArtifact(GetID());
            if (artifact != null)
            {
                var velocity = shootParams.velocity;
                var angle = artifact.RNG.Next(0, 360f);
                shootParams.velocity = velocity.RotateClockwiseXZ(angle);

                shootParams.spawnParam.SetProperty(VanillaProjectileProps.DIRECTION_CHANGED_BY_KRAKENS_TENTACLE, true);

                artifact.Highlight();
            }
        }
        public class Aura : AuraEffectDefinition
        {
            public Aura() : base(VanillaBuffID.Contraption.krakensTentacleAttackSpeed)
            {
            }

            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                var level = auraEffect.Source.GetLevel();
                results.AddRange(level.FindEntities(e => e.Type == EntityTypes.PLANT && e.IsFriendlyEntity()));
            }
        }
    }
}
